using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Media.Media3D;using ToneCustoms.ShellStudio.Core;
namespace ToneCustoms.ShellStudio.Editor;
public sealed class Viewport3DControl:Grid { readonly Viewport3D view=new();readonly Model3DGroup scene=new();readonly PerspectiveCamera camera=new(){FieldOfView=55,Position=new Point3D(10,-12,9),LookDirection=new Vector3D(-10,12,-7),UpDirection=new Vector3D(0,0,1)};ShellProject? project;Point? orbitStart;double yaw=.7,pitch=.55,distance=18;public Viewport3DControl(){Background=new SolidColorBrush(Color.FromRgb(12,12,16));view.Camera=camera;view.Children.Add(new ModelVisual3D{Content=scene});Children.Add(view);MouseWheel+=Wheel;MouseRightButtonDown+=Down;MouseRightButtonUp+=Up;MouseMove+=Move;Loaded+=(_,_)=>RenderScene();}public void SetProject(ShellProject p){project=p;RenderScene();}public void RenderScene(){scene.Children.Clear();scene.Children.Add(new AmbientLight(Color.FromRgb(105,105,120)));scene.Children.Add(new DirectionalLight(Colors.White,new Vector3D(-.4,.6,-1)));DrawGrid();if(project==null)return;foreach(var o in project.Objects)scene.Children.Add(Box(o));}GeometryModel3D Box(SceneObject o){var sx=Math.Max(.02,o.Scale.X)/2;var sy=Math.Max(.02,o.Scale.Y)/2;var sz=Math.Max(.02,o.Scale.Z)/2;var pts=new Point3DCollection{new(-sx,-sy,-sz),new(sx,-sy,-sz),new(sx,sy,-sz),new(-sx,sy,-sz),new(-sx,-sy,sz),new(sx,-sy,sz),new(sx,sy,sz),new(-sx,sy,sz)};var idx=new Int32Collection{0,2,1,0,3,2,4,5,6,4,6,7,0,1,5,0,5,4,1,2,6,1,6,5,2,3,7,2,7,6,3,0,4,3,4,7};var mesh=new MeshGeometry3D{Positions=pts,TriangleIndices=idx};var color=o.Type==SceneObjectType.Prop?Color.FromRgb(125,90,190):Color.FromRgb(105,76,165);var model=new GeometryModel3D(mesh,new DiffuseMaterial(new SolidColorBrush(color))){BackMaterial=new DiffuseMaterial(new SolidColorBrush(color))};var t=new Transform3DGroup();t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(1,0,0),o.Rotation.X)));t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(0,1,0),o.Rotation.Y)));t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(0,0,1),o.Rotation.Z)));t.Children.Add(new TranslateTransform3D(o.Position.X,o.Position.Y,o.Position.Z));model.Transform=t;return model;}void DrawGrid(){for(int i=-20;i<=20;i++){scene.Children.Add(Line(new Point3D(i,-20,0),new Point3D(i,20,0)));scene.Children.Add(Line(new Point3D(-20,i,0),new Point3D(20,i,0)));}}GeometryModel3D Line(Point3D a,Point3D b){var d=b-a;var len=d.Length;var mesh=new MeshGeometry3D{Positions=new Point3DCollection{new(-.01,-len/2,0),new(.01,-len/2,0),new(.01,len/2,0),new(-.01,len/2,0)},TriangleIndices=new Int32Collection{0,1,2,0,2,3}};var m=new GeometryModel3D(mesh,new DiffuseMaterial(new SolidColorBrush(Color.FromRgb(42,42,52))));var angle=Math.Atan2(d.Y,d.X)*180/Math.PI-90;var t=new Transform3DGroup();t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(0,0,1),angle)));t.Children.Add(new TranslateTransform3D((a.X+b.X)/2,(a.Y+b.Y)/2,0));m.Transform=t;return m;}void Down(object s,MouseButtonEventArgs e){orbitStart=e.GetPosition(this);CaptureMouse();}void Up(object s,MouseButtonEventArgs e){orbitStart=null;ReleaseMouseCapture();}void Move(object s,MouseEventArgs e){if(orbitStart==null||e.RightButton!=MouseButtonState.Pressed)return;var p=e.GetPosition(this);yaw+=(p.X-orbitStart.Value.X)*.01;pitch=Math.Clamp(pitch+(p.Y-orbitStart.Value.Y)*.01,-1.35,1.35);orbitStart=p;UpdateCamera();}void Wheel(object s,MouseWheelEventArgs e){distance=Math.Clamp(distance-e.Delta/120.0,3,80);UpdateCamera();}void UpdateCamera(){var cp=Math.Cos(pitch);var pos=new Point3D(Math.Cos(yaw)*cp*distance,Math.Sin(yaw)*cp*distance,Math.Sin(pitch)*distance+3);camera.Position=pos;camera.LookDirection=new Vector3D(-pos.X,-pos.Y,1.5-pos.Z);}}
